func newRateConfirmationToken() unsafe.Pointer {
	return unsafe.Pointer(new(rateconfirmation.RateConfirmationToken))
}

func newNRateConfirmationToken(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]rateconfirmation.RateConfirmationToken, n)))
}

func ptrRateConfirmationToken(p unsafe.Pointer, c int32) any {
	r := (*rateconfirmation.RateConfirmationToken)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RateConfirmationID))
	case 4:
		return &r.TokenHash
	case 5:
		return &r.Email
	case 6:
		return &r.ExpiresAt
	case 7:
		return &r.UsedAt
	case 8:
		return &r.RevokedAt
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueRateConfirmationToken(p unsafe.Pointer, c int32) any {
	r := (*rateconfirmation.RateConfirmationToken)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RateConfirmationID)
	case 4:
		return r.TokenHash
	case 5:
		return r.Email
	case 6:
		return r.ExpiresAt
	case 7:
		if r.UsedAt == nil {
			return nil
		}
		return *r.UsedAt
	case 8:
		if r.RevokedAt == nil {
			return nil
		}
		return *r.RevokedAt
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

func attachRateConfirmationToken(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*rateconfirmation.RateConfirmationToken)(p)
	switch rel {
	case 0:
		r.RateConfirmation = (*rateconfirmation.RateConfirmation)(child)
	}
}

func init() {
	rateConfirmationsTable.Relations[0].Target = carrierdb.CarriersSchema()
	rateConfirmationsTable.Relations[1].Target = shipmentdb.CarrierAssignmentsSchema()
	rateConfirmationsTable.Relations[2].Target = shipmentdb.ShipmentsSchema()
	rateConfirmationTokensTable.Relations[0].Target = RateConfirmationsSchema()
}

